import{_ as a,a0 as n,w as u,s as p,ao as s,I as e,x as r,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"VirturalBox 終於進入到 5.0 世代 | LCTT x X-CMD","titleTemplate":false,"description":"VirturalBox 終於進入到 5.0 世代 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"VirturalBox 終於進入到 5.0 世代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"VirturalBox 終於進入到 5.0 世代 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150402 The VirtualBox 5.0 beta is finally here","title":"VirturalBox 終於進入到 5.0 世代","tag":"201504","desc":""},"relativePath":"201504/20150402 The VirtualBox 5.0 beta is finally here.md","filePath":"[post].md"}'),x={name:"201504/20150402 The VirtualBox 5.0 beta is finally here.md"};function f(d,t,m,V,T,B){const l=n("Link");return u(),p("div",null,[t[18]||(t[18]=s('<h1 id="virturalbox-終於進入到-5-0-世代" tabindex="-1">VirturalBox 終於進入到 5.0 世代 <a class="header-anchor" href="#virturalbox-終於進入到-5-0-世代" aria-label="Permalink to “VirturalBox 終於進入到 5.0 世代”">​</a></h1><p><strong>本月初，甲骨文公司的桌面虛擬化軟件獲得了近五年來的第一次重大改版，但是更像是改進而不是革命性的的變化。</strong></p><p>VirtualBox，由Sun公司創建，現在由甲骨文管理的開源虛擬化系統，獲得了近5年來第一次的主版本更新發布。</p><p>從發行説明和測試版本身的表現來看，別期望任何真正革命性的改變。在此版本中，VirtualBox在視覺上和技術上都做了一些改進，但和VMware相比，它的主要優勢仍然是相同核心功能的開源實現。</p><p>VirtualBox 4.0的最後一個主要版本在2010年12月發佈，它採用了新的圖形化用户界面，新的虛擬化硬件和重組的項目設計，進行了重大的改版。但項目主要版本的發佈步伐緩慢，上一次重要版本(版本4.3)在2013年底才發佈。從那時起，一切都被正式稱為“維護”發佈。</p><p><img src="http://images.techhive.com/images/article/2015/04/vbox-5-100576781-large.idge.png" alt=""></p><p><em>VirtualBox 5.0的第一個測試版增加了編輯菜單，VM窗口的快捷方式圖標等功能，如下面所示。</em></p><p>VirtualBox 5.0最大的變化是增加了對硬件輔助虛擬化指令集擴展的支持。AES-NI指令集通常用於加密時的硬件加速，SSE 4.1和SSE 4.2指令集都包括在其中。另外一點是支持Windows和Linux客户機的半虛擬化，一個抽象主機音響設備的新的架構以及支持客户機中的USB 3（xHCI）控制器。</p><p>大部分可用性更新都是對 VirtualBox 圖形化用户界面的改進。一個大的變化就是支持給單個虛擬主機自定義菜單和工具欄，這樣很少或者從不使用的選項就可以徹底刪除。另外重要的一點是可以在VirtualBox接口內部對虛擬磁盤進行加密，而不依賴於客户機操作系統自身的磁盤加密功能(假設有的話)。</p><p>甲骨文公司提醒由於這是個測試版軟件，需要謹慎對待。當然，主界面和客户機系統界面的某個角落打着紅黑相間的測試警告標誌。但之前VirtualBox發行版(4.3.26)上創建的Windows 10虛擬機啓動和運行都沒問題，5.0版本中添加的VirtualBox客户機功能--更好的視頻支持，雙向複製和粘貼，以及其它功能--在安裝的時候也沒有問題。(從4.3.18版本就改進了對 Windows 10的支持)。</p>',10)),e("p",null,[t[2]||(t[2]=r("雖然沒有明確指出5.0的最終版什麼時候會發布，但是甲骨文公司",-1)),i(l,{href:"https://forums.virtualbox.org/viewtopic.php?f=15&t=66904"},{default:o(()=>[...t[0]||(t[0]=[r("建議用户",-1)])]),_:1}),t[3]||(t[3]=r("在非生產環境中下載和使用測試版，並在",-1)),i(l,{href:"https://forums.virtualbox.org/viewforum.php?f=15"},{default:o(()=>[...t[1]||(t[1]=[r("測試版反饋論壇",-1)])]),_:1}),t[4]||(t[4]=r("中提交bug報告。",-1))]),t[19]||(t[19]=e("hr",null,null,-1)),e("p",null,[t[6]||(t[6]=r("via: ",-1)),i(l,{href:"http://www.infoworld.com/article/2905098/virtualization/oracle-virtualbox-5-0-beta-is-finally-here.html"},{default:o(()=>[...t[5]||(t[5]=[r("http://www.infoworld.com/article/2905098/virtualization/oracle-virtualbox-5-0-beta-is-finally-here.html",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=r("作者：",-1)),i(l,{href:"http://www.infoworld.com/author/Serdar-Yegulalp/"},{default:o(()=>[...t[7]||(t[7]=[r("Serdar Yegulalp",-1)])]),_:1}),t[11]||(t[11]=r(" 譯者：",-1)),i(l,{href:"https://github.com/ictlyh"},{default:o(()=>[...t[8]||(t[8]=[r("ictlyh",-1)])]),_:1}),t[12]||(t[12]=r(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=r("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原創翻譯，",-1)),i(l,{href:"http://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[r("Linux中國",-1)])]),_:1}),t[17]||(t[17]=r(" 榮譽推出",-1))])])}const C=a(x,[["render",f]]);export{b as __pageData,C as default};
